def _process_provides_extra(
    self,
    value: list[str],
) -> list[utils.NormalizedName]:
    normalized_names = []
    try:
        for name in value:
            normalized_names.append(utils.canonicalize_name(name, validate=True))
    except utils.InvalidName as exc:
        raise self._invalid_metadata(
            f"{name!r} is invalid for {self.raw_name!r}", cause=exc
        ) from exc
    else:
        return normalized_names

def _extract_extras_from_marker(
    markers: MarkerList,
) -> set[str]:
    """Extract extra names from a marker expression.

    Only considers comparisons of the form `extra == "name"` or `"name" == extra`.
    Does not recurse into `and`/`or` branches for the "in extras" form.
    Returns a set of canonicalized extra names.
    """
    extras: set[str] = set()
    for item in markers:
        if isinstance(item, str):
            # "and" or "or" - skip
            continue
        if isinstance(item, tuple):
            lhs, op, rhs = item
            if isinstance(lhs, Variable) and lhs.value == "extra" and isinstance(rhs, Value):
                extras.add(canonicalize_name(rhs.value))
            elif isinstance(rhs, Variable) and rhs.value == "extra" and isinstance(lhs, Value):
                extras.add(canonicalize_name(lhs.value))
        elif isinstance(item, list):
            # Nested list (from grouping) - recurse
            extras |= _extract_extras_from_marker(item)
    return extras
